def wolfeCompactReciprocal (a : JLMS.CZero 𝕜 L) (ha : ∀ x, a x ≠ 0) : JLMS.CZero 𝕜 L :=
  (JLMS.compactContinuousCZeroEquiv (𝕜 := 𝕜) (K := L))
    ⟨fun x => (a x)⁻¹, a.continuous.inv₀ ha⟩

